(root/'templates'/'respond_trade_request.html').write_text('''{% extends "base.html" %}\n{% from "_card_macros.html" import showcase_card %}\n{% block content %}\n<div class="exchange-container">\n    <h1>Отклик на запрос</h1>\n    <div class="exchange-card">\n        <h2>Пользователь {{ trade_request.requester.username }} хочет получить</h2>\n        {{ showcase_card(card=trade_request.requested_card, rarity=trade_request.requested_card.rarity, letter=get_card_letter(trade_request.requested_card), subject=trade_request.requested_card.subject, description=trade_request.requested_card.description, stars='', meta_items=[{'label':'Запрос','value':'Открыт'}], action_html='') }}\n    </div>\n    <div class="exchange-card">\n        <h2>Выберите, что хотите получить от пользователя</h2>\n        <form method="POST">\n            <input type="hidden" name="requested_card_id" id="requested_card_input">\n            <div class="items-grid collection-grid collection-grid-enhanced selectable-grid">\n                {% for user_card in target_cards %}\n                <button type="button" class="card-select-button" data-card-choice="{{ user_card.card.id }}">\n                    {{ showcase_card(card=user_card.card, rarity=user_card.card.rarity, letter=get_card_letter(user_card.card), subject=user_card.card.subject, description=user_card.card.description, stars=get_card_stars_display(user_card.star_level), meta_items=[{'label':'Копий у пользователя','value':user_card.quantity}], action_html='') }}\n                </button>\n                {% endfor %}\n            </div>\n            <div class="exchange-form-actions"><button type="submit" class="btn">Отправить предложение</button></div>\n        </form>\n    </div>\n</div>\n<script>document.addEventListener('DOMContentLoaded',()=>{const input=document.getElementById('requested_card_input');document.querySelectorAll('[data-card-choice]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-card-choice]').forEach(b=>b.classList.remove('selected'));btn.classList.add('selected');input.value=btn.dataset.cardChoice;}));});</script>\n{% endblock %}\n''', encoding='utf-8')

(root/'templates'/'card_owners.html').write_text('''{% extends "base.html" %}\n{% from "_card_macros.html" import showcase_card %}\n{% block content %}\n<div class="collection-page">\n    <div class="collection-hero hero-slim">\n        <div><h1>У кого есть карточка</h1><p class="collection-hint">Здесь можно посмотреть владельцев карточки и перейти к обмену.</p></div>\n    </div>\n    <div class="exchange-card">\n        {{ showcase_card(card=card, rarity=card.rarity, letter=get_card_letter(card), subject=card.subject, description=card.description, stars='', meta_items=[{'label':'Редкость','value':card.rarity},{'label':'Коллекционная ценность','value':card.base_price}], action_html='') }}\n    </div>\n    <div class="items-grid">\n        {% for owner in owners %}\n        <div class="shop-item">\n            <h3>{{ owner.user.username }}</h3>\n            <p>Копий: {{ owner.quantity }}</p>\n            <div class="trade-actions">\n                <a class="btn btn-secondary" href="{{ url_for('view_profile', user_id=owner.user.id) }}">Открыть профиль</a>\n                <a class="btn" href="{{ url_for('propose_exchange', target_user_id=owner.user.id, requested_card_id=card.id) }}">Предложить обмен</a>\n            </div>\n        </div>\n        {% else %}\n        <div class="shop-item"><p>Пока ни у кого нет этой карточки, кроме вас.</p></div>\n        {% endfor %}\n    </div>\n</div>\n{% endblock %}\n''', encoding='utf-8')

# cards & wishlist make title click/open owners page and action buttons
for fname in ['cards.html','wishlist.html']:
    p = root/'templates'/fname
    t = p.read_text(encoding='utf-8')
    t = t.replace("action_html=action_html", "action_html=action_html ~ '<a class=\"btn btn-secondary\" href=\"' ~ url_for('card_owners', card_id=card.id) ~ '\">У кого есть</a>'")
    p.write_text(t, encoding='utf-8')

# profile buttons link to propose_exchange and owners for wishlist modal
p = root/'templates'/'profile.html'
t = p.read_text(encoding='utf-8')
t = t.replace("<a href=\"{{ url_for('exchange', target_user_id=user.id, requested_card_id=user_card.card.id) }}\" class=\"btn\">Обмен</a>", "<a href=\"{{ url_for('propose_exchange', target_user_id=user.id, requested_card_id=user_card.card.id) }}\" class=\"btn\">Предложить обмен</a>")
t = t.replace("<div class=\"profile-card-actions\">\n                            <form method=\"post\" action=\"{{ url_for('toggle_wishlist', card_id=card.id) }}\">", "<div class=\"profile-card-actions\">\n                            <a href=\"{{ url_for('card_owners', card_id=card.id) }}\" class=\"btn btn-secondary\">У кого есть</a>\n                            <form method=\"post\" action=\"{{ url_for('toggle_wishlist', card_id=card.id) }}\">")
p.write_text(t, encoding='utf-8')

# CSS append
css = root/'static/css/style.css'
with css.open('a', encoding='utf-8') as f:
    f.write('''\n\nselectable-grid{}\n.card-select-button{display:block;width:100%;padding:0;border:0;background:transparent;cursor:pointer;text-align:left;}\n.card-select-button .card-showcase{height:100%;}\n.card-select-button.selected .card-showcase{outline:2px solid var(--green);box-shadow:0 0 0 2px rgba(57,255,136,.18),0 0 24px rgba(57,255,136,.2);}\n.nav-container{flex-wrap:nowrap;}\n.nav-main{flex:1;min-width:0;}\n.nav-menu{flex-wrap:nowrap;gap:.5rem;overflow-x:auto;padding-bottom:.2rem;}\n.nav-actions{display:flex;align-items:center;gap:.55rem;flex-shrink:0;}\n.shop-tabs{display:flex;gap:1rem;flex-wrap:wrap;margin:1rem 0 1.5rem;}\n.profile-card-actions{display:flex;gap:.8rem;align-items:center;flex-wrap:wrap;}\nselect, option{background:#121727;color:#eef2ff;}\n''')
